  ('c429893a-8e5e-4f7b-9464-518a674b5ae0','b1f63336-4614-4c12-9b03-6ad3c30604df','la_socrata','1459908','needs_research',
   'Vargas for City Council 2024',
   'surname-only auto-link: LA City Ethics committee 1459908 "Vargas for City Council 2024" -- LA City Ethics names its candidate as Eduardo Vargas (LA City Council Member - District 14), a different person; this row is Yarma Velázquez Vargas, Board Member (District 7), Pasadena Unified');

-- the displayed total and the status counts on active rows, before anything moves
CREATE TEMP TABLE _before ON COMMIT DROP AS
SELECT (SELECT COALESCE(sum(a.total_amount), 0) FROM transparent_motivations.contribution_summary_agg a
          JOIN transparent_motivations.politician_sources ps ON ps.id = a.politician_source_id
         WHERE ps.research_status = 'confirmed') AS confirmed_total,
       (SELECT count(*) FROM transparent_motivations.politician_sources ps
          JOIN essentials.politicians p ON p.id = ps.essentials_politician_id
         WHERE p.is_active AND ps.research_status = 'confirmed') AS active_confirmed,
       (SELECT count(*) FROM transparent_motivations.politician_sources ps
          JOIN essentials.politicians p ON p.id = ps.essentials_politician_id
         WHERE p.is_active AND ps.research_status = 'not_applicable') AS active_not_applicable,
       (SELECT count(*) FROM transparent_motivations.politician_sources ps
          JOIN essentials.politicians p ON p.id = ps.essentials_politician_id
         WHERE p.is_active AND ps.research_status = 'disputed' AND strpos(ps.notes, 'CA_0178 (2026-09-23)') = 0) AS active_disputed_other;


-- ─── Pre-flight ──────────────────────────────────────────────────────────────────────────────────
DO $$
DECLARE v_n int; v_md5 text;
BEGIN
  SELECT count(*) INTO v_n FROM _link;
  IF v_n <> 680 THEN RAISE EXCEPTION 'PRE: _link holds %, expected 680', v_n; END IF;

  -- each link is the recorded (row, system, committee id, stored committee name), still at its reviewed status
  -- (or already disputed by an earlier run of this file), on an ACTIVE row
  SELECT count(*) INTO v_n FROM _link l
    JOIN transparent_motivations.politician_sources ps ON ps.id = l.id
    JOIN essentials.politicians p ON p.id = ps.essentials_politician_id
   WHERE ps.essentials_politician_id = l.politician_id
     AND ps.source_system = l.source_system AND ps.external_id = l.external_id
     AND COALESCE(split_part(ps.notes, ' | ', 1)::jsonb ->> 'committee_name',
                  split_part(ps.notes, ' | ', 1)::jsonb ->> 'cmt_nm') = l.committee
     AND (ps.research_status = l.prior_status
          OR (ps.research_status = 'disputed' AND strpos(ps.notes, 'CA_0178 (2026-09-23)') > 0))
     AND p.is_active;
  IF v_n <> 680 THEN RAISE EXCEPTION 'PRE: % of 680 links match their reviewed record on an active row', v_n; END IF;

  -- the review was complete: the reviewed population is every needs_research link on an active row (1,886, measured
  -- 2026-09-23), pinned by count AND by an md5 of the sorted ids. Links this file already disputed are counted back
  -- in, so a re-run passes. A link added, removed or re-pointed since the review fails here instead of being skipped.
  SELECT count(*), md5(string_agg(ps.id::text, ',' ORDER BY ps.id)) INTO v_n, v_md5
    FROM transparent_motivations.politician_sources ps
    JOIN essentials.politicians p ON p.id = ps.essentials_politician_id
   WHERE p.is_active
     AND (ps.research_status = 'needs_research'
          OR (ps.research_status = 'disputed' AND strpos(ps.notes, 'CA_0178 (2026-09-23)') > 0));
  IF v_n <> 1886 OR v_md5 <> '9b92e42b508b865595c6975db50a2548' THEN
    RAISE EXCEPTION 'PRE: the reviewed population changed: % links, md5 % (expected 1886, 9b92e42b508b865595c6975db50a2548)', v_n, v_md5;
  END IF;
END $$;

-- ─── 1. Dispute the 680 links ─────────────────────────────────────────────────────────────────
UPDATE transparent_motivations.politician_sources ps
   SET research_status = 'disputed',
       notes = CASE WHEN ps.notes IS JSON OBJECT
                    THEN (ps.notes::jsonb || jsonb_build_object('disputed_by', 'CA_0178 (2026-09-23)', 'disputed_reason', l.reason))::text
                    ELSE ps.notes || ' | DISPUTED by CA_0178 (2026-09-23): ' || l.reason END,
       updated_at = now()
  FROM _link l
 WHERE ps.id = l.id AND ps.research_status = l.prior_status;

-- ─── Post-verify gate ────────────────────────────────────────────────────────────────────────────
DO $$
DECLARE v_n int; v_amt numeric; v_ids uuid[]; b record;
BEGIN
  SELECT * INTO b FROM _before;

  SELECT count(*) INTO v_n FROM transparent_motivations.politician_sources ps JOIN _link l ON l.id = ps.id
   WHERE ps.research_status = 'disputed'
     AND ((ps.notes IS JSON OBJECT AND ps.notes::jsonb ->> 'disputed_by' = 'CA_0178 (2026-09-23)' AND ps.notes::jsonb ->> 'disputed_reason' = l.reason)
          OR right(ps.notes, length(' | DISPUTED by CA_0178 (2026-09-23): ' || l.reason)) = ' | DISPUTED by CA_0178 (2026-09-23): ' || l.reason);
  IF v_n <> 680 THEN RAISE EXCEPTION 'POST: % of 680 links disputed with their reason', v_n; END IF;

  -- nothing outside _link carries this file's marker
  SELECT count(*) INTO v_n FROM transparent_motivations.politician_sources ps
   WHERE strpos(ps.notes, 'CA_0178 (2026-09-23)') > 0 AND NOT EXISTS (SELECT 1 FROM _link l WHERE l.id = ps.id);
  IF v_n <> 0 THEN RAISE EXCEPTION 'POST: % link(s) outside _link carry the CA_0178 marker', v_n; END IF;

  -- the 1,206 kept links are still needs_research, and no other status on active rows moved
  SELECT count(*) INTO v_n FROM transparent_motivations.politician_sources ps
    JOIN essentials.politicians p ON p.id = ps.essentials_politician_id
   WHERE p.is_active AND ps.research_status = 'needs_research';
  IF v_n <> 1206 THEN RAISE EXCEPTION 'POST: % needs_research links on active rows, expected 1206 (1886 - 680)', v_n; END IF;

  SELECT count(*) INTO v_n FROM transparent_motivations.politician_sources ps
    JOIN essentials.politicians p ON p.id = ps.essentials_politician_id
   WHERE p.is_active AND ps.research_status = 'confirmed';
  IF v_n <> b.active_confirmed THEN RAISE EXCEPTION 'POST: confirmed links on active rows moved % -> %', b.active_confirmed, v_n; END IF;

  SELECT count(*) INTO v_n FROM transparent_motivations.politician_sources ps
    JOIN essentials.politicians p ON p.id = ps.essentials_politician_id
   WHERE p.is_active AND ps.research_status = 'not_applicable';
  IF v_n <> b.active_not_applicable THEN RAISE EXCEPTION 'POST: not_applicable links on active rows moved % -> %', b.active_not_applicable, v_n; END IF;

  SELECT count(*) INTO v_n FROM transparent_motivations.politician_sources ps
    JOIN essentials.politicians p ON p.id = ps.essentials_politician_id
   WHERE p.is_active AND ps.research_status = 'disputed';
  IF v_n <> b.active_disputed_other + 680 THEN
    RAISE EXCEPTION 'POST: % disputed links on active rows, expected % (earlier) + 680', v_n, b.active_disputed_other;
  END IF;

  -- no money hangs off these links, and nothing was deleted
  -- ids through an array, not a temp-table subquery: contributions is large and the planner has no stats on _link
  SELECT array_agg(id) INTO v_ids FROM _link;
  SELECT count(*) INTO v_n FROM transparent_motivations.contributions WHERE politician_source_id = ANY (v_ids);
  IF v_n <> 0 THEN RAISE EXCEPTION 'POST: % contributions on the 680 sources, expected 0', v_n; END IF;
  SELECT count(*) INTO v_n FROM transparent_motivations.contribution_summary_agg WHERE politician_source_id = ANY (v_ids);
  IF v_n <> 0 THEN RAISE EXCEPTION 'POST: % aggregate rows on the 680 sources, expected 0', v_n; END IF;
  SELECT count(*) INTO v_n FROM transparent_motivations.ingestion_runs WHERE politician_source_id = ANY (v_ids);
  IF v_n <> 157 THEN RAISE EXCEPTION 'POST: % ingestion_runs on the 680 sources, expected 157 (untouched)', v_n; END IF;

  -- the confirmed total did not move
  SELECT b.confirmed_total - (SELECT COALESCE(sum(a.total_amount), 0) FROM transparent_motivations.contribution_summary_agg a
                               JOIN transparent_motivations.politician_sources ps ON ps.id = a.politician_source_id
                              WHERE ps.research_status = 'confirmed')
    INTO v_amt;
  IF v_amt <> 0 THEN RAISE EXCEPTION 'POST: the confirmed total moved by %, expected 0', v_amt; END IF;

  RAISE NOTICE 'CA_0178 applied: 680 wrong committee links disputed on active rows; 1,206 left needs_research; no money moved';
END $$;

COMMIT;
